local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule

local CellName = "Cell"
local CellPath = 'Game.OverseaChat.OverseaChatFriendCell'

---@type FriendComponent
local FriendComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.FriendComponent)

---@class OverseaChatFriendEntryPanel
---@field ListView SuperScrollView.LoopGridView
local OverseaChatFriendEntryPanel = Class('OverseaChatFriendEntryPanel')

function OverseaChatFriendEntryPanel:__init()
    self.data = nil
    ---@type OverseaChatMainDialog
    self.env = nil
end

function OverseaChatFriendEntryPanel:__delete()
    self.data = nil
    ---@type OverseaChatMainDialog
    self.env = nil
end

function OverseaChatFriendEntryPanel:GetFriendData(playerId)
    return FriendComp:GetFriendInfo(playerId) or {}
end

---Refresh
---@param env OverseaChatMainDialog
function OverseaChatFriendEntryPanel:Refresh(env)
    self.data = {}--clone(checkTable(FriendComp:GetFriendList()))
    for index, friendData in ipairs(checkTable(FriendComp:GetFriendList())) do
        self.data[index] = checkInt(friendData.friendId)
    end
    local social = AppService:GetInstance():GetSocialLine()
    local msgDatas = social:GetUnreadMsgDataByPlayerId()
    table.sort(self.data, function(a, b)
        local aFriend = self:GetFriendData(a)
        local bFriend = self:GetFriendData(b)
        local aNewMsg = msgDatas[tostring(a)] ~= nil
        local bNewMsg = msgDatas[tostring(b)] ~= nil
        if aNewMsg ~= bNewMsg then
            return aNewMsg
        else
            return checkInt(aFriend.isOnline) > checkInt(bFriend.isOnline)
        end 
    end)
    self.env = env
    if not self.ListView.IsListViewInit then
        self.ListView:InitGridView(#self.data, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ListView, #self.data)
    end
end

function OverseaChatFriendEntryPanel:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local position = index + 1
    local friendData = self:GetFriendData(self.data[position])
    if isNull(friendData) then return end
    local cell = listView:NewListViewItem(CellName)
    ---@type OverseaChatFriendCell
    local env = CfUtils.GetLuaScr(cell.gameObject, CellPath)
    if not KTool.IsNull(env) then
        env:FreshUI(friendData, Bind(self, self.OnStartChatAction))
    end
    return cell
end

function OverseaChatFriendEntryPanel:OnStartChatAction(data)
    print('--->>', table.dump(data, false, 2))
    self.env:RefreshPrivateData(data)
end

function OverseaChatFriendEntryPanel:OnDestroy()
    ---@type OverseaChatMainDialog
    self.env = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return OverseaChatFriendEntryPanel